    out = [row[:] for row in grid]

    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    bg = max(counts, key=counts.get)

    # The interior singleton/marker color is distinguished from the long
    # colored runs along the edges.
    edge_values = set()
    for c in range(w):
        edge_values.add(grid[0][c])
        edge_values.add(grid[h - 1][c])
    for r in range(h):
        edge_values.add(grid[r][0])
        edge_values.add(grid[r][w - 1])
    marker = next(
        (v for v in counts if v != bg and v not in edge_values),
        None
    )
    if marker is None:
        # In some cases markers share a color with an edge cell.
        marker = min((v for v in counts if v != bg),
                     key=lambda v: counts[v])

    def project(r, c, dr, dc):
        rr, cc = r + dr, c + dc
        while 0 <= rr < h and 0 <= cc < w:
            if grid[rr][cc] == marker:
                out[rr][cc] = 4
                break
            if grid[rr][cc] != bg:
                break
            out[rr][cc] = marker
            rr += dr
            cc += dc

    # Edge bars project inward, stopping at marker points.
    for c in range(w):
        if grid[0][c] != bg and grid[0][c] != marker:
            project(0, c, 1, 0)
        if grid[h - 1][c] != bg and grid[h - 1][c] != marker:
            project(h - 1, c, -1, 0)
    for r in range(h):
        if grid[r][0] != bg and grid[r][0] != marker:
            project(r, 0, 0, 1)
        if grid[r][w - 1] != bg and grid[r][w - 1] != marker:
            project(r, w - 1, 0, -1)

    # Highlight all interior markers, including ones not reached by a beam.
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if grid[r][c] == marker:
                out[r][c] = 4

    return out
